import pytest
from backend.models import NormalizedEvent, Incident
from datetime import datetime

def test_regression_inc004_normalization():
    # Simulate the raw event generated by the simulator from surat_monsoon.json
    ev = NormalizedEvent(
        event_id="SIM-E04",
        timestamp="10:00:00",
        source="simulated_dispatch_feed",
        source_type="simulation",
        event_type="new_incident",
        location="Adajan",
        payload={
            "incident_id": "INC-004",
            "type": "Gas Leak",
            "severity": 8,
            "urgency": "HIGH",
            "required_units": {"rescue_team": 1, "ambulance": 1},
            "people_affected": 15,
            "lat": 21.1959,
            "lon": 72.7933
        }
    )

    # Perform the normalization logic implemented in app.py
    inc_data = ev.payload.copy()
    if "incident_id" in inc_data:
        inc_data["id"] = inc_data.pop("incident_id")
    if "location" not in inc_data and hasattr(ev, "location"):
        inc_data["location"] = ev.location
    if "lat" in inc_data:
        inc_data["latitude"] = inc_data.pop("lat")
    if "lon" in inc_data:
        inc_data["longitude"] = inc_data.pop("lon")

    # Validate against the unchanged Pydantic model
    inc = Incident(**inc_data)

    # Asserts to ensure it parsed correctly without arbitrary defaults
    assert inc.id == "INC-004"
    assert inc.location == "Adajan"
    assert inc.latitude == 21.1959
    assert inc.longitude == 72.7933
    assert inc.people_affected == 15
    assert inc.severity == 8
    assert inc.type == "Gas Leak"
